import{CONFIG}from"./config.min.js";class ReadingModeManager{constructor(){this.currentMode=this.loadMode()}init(){this.applyMode(this.currentMode,!1);const e=document.getElementById("readingModeToggle");if(!CONFIG.showReadingModeToggle&&e)return void(e.style.display="none");document.querySelectorAll(".mode-btn").forEach(e=>{e.addEventListener("click",e=>{const t=e.target.dataset.mode;t!==this.currentMode&&this.switchMode(t)})}),this.updateToggleUI()}loadMode(){return localStorage.getItem("readingMode")||CONFIG.defaultReadingMode||"scroll"}saveMode(e){localStorage.setItem("readingMode",e)}switchMode(e){const t=window.currentChapterId;this.currentMode=e,this.saveMode(e),this.applyMode(e,!0),this.updateToggleUI(),window.readerInstance&&t&&window.readerInstance.loadChapter(t,0),window.dispatchEvent(new CustomEvent("readingModeChanged",{detail:{mode:e}}))}applyMode(e,t=!1){const d=document.body;"page"===e?(d.classList.add("paginated"),d.classList.remove("scrolling")):(d.classList.add("scrolling"),d.classList.remove("paginated"))}updateToggleUI(){document.querySelectorAll(".mode-btn").forEach(e=>{e.dataset.mode===this.currentMode?(e.classList.add("active"),e.setAttribute("aria-pressed","true")):(e.classList.remove("active"),e.setAttribute("aria-pressed","false"))})}getMode(){return this.currentMode}isPageMode(){return"page"===this.currentMode}isScrollMode(){return"scroll"===this.currentMode}}const readingModeManager=new ReadingModeManager;export{readingModeManager};window.readingModeManager=readingModeManager;